//! Weight functions for pallet-weights. `()` holds the estimates used until the runtime ships
//! benchmarked weights (runtime/src/weights/, generated by scripts/run-benchmarks.sh).
#![allow(unused_parens, unused_imports)]

use polkadot_sdk::frame_support::weights::{constants::RocksDbWeight, Weight};

pub trait WeightInfo {
    fn commit_weights() -> Weight;
    fn reveal_weights(n: u32) -> Weight;
}

impl WeightInfo for () {
    fn commit_weights() -> Weight {
        RocksDbWeight::get().reads_writes(2, 1)
    }
    fn reveal_weights(n: u32) -> Weight {
        RocksDbWeight::get()
            .reads_writes(2, 2)
            .saturating_add(Weight::from_parts(20_000 * n as u64, 0))
    }
}
